const items = $input.all();

return items
  .filter(item => item.json.status === 'published')
  .map((item, index) => ({
    json: {
      ...item.json,
      row_id: index + 2,
      sheet_url: `https://docs.google.com/spreadsheets/d/1Gdqn7krlhpgKi__3h6xKjOm0XZ12usftoorXJTD7LII/edit#gid=0&range=A${index + 2}`
    }
  }));

const j = $input.item.json;

return {
  json: {
    row_id: j.row_id,
    sheet_url: j.sheet_url,
    row: {
      status: j.status,
      trending_keyword: j.trending_keyword,
      abstract: j.abstract || '',
      segment: j.segment || j.default_segment || 'Cold',
      generated_title: j.generated_title,
      generated_body: j.generated_body,
      note_url: j.note_url,
      note_title: j.note_title,
      note_pv: j.note_pv ?? 0,
      note_likes: j.note_likes ?? 0,
      note_conversion: j.note_conversion ?? 0.0
    }
  }
};

parameters.jsonSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "next_decision": {
      "type": "string",
      "enum": ["improve", "pause", "scale"],
      "description": "次の打ち手の方向性"
    },
    "next_action": {
      "type": "string",
      "maxLength": 200,
      "minLength": 1,
      "description": "具体的なアクション（200文字以内）"
    },
    "next_segment": {
      "type": "string",
      "enum": ["Cold", "Middle", "Hot", "Current"],
      "description": "推奨セグメント"
    },
    "next_keyword_idea": {
      "type": "string",
      "maxLength": 100,
      "minLength": 1,
      "description": "次のキーワード案（100文字以内）"
    },
    "insights": {
      "type": "array",
      "items": {
        "type": "string",
        "maxLength": 200
      },
      "minItems": 2,
      "maxItems": 4,
      "description": "分析インサイト（2-4個）"
    },
    "reasoning": {
      "type": "string",
      "maxLength": 500,
      "minLength": 1,
      "description": "判断理由（500文字以内）"
    }
  },
  "required": [
    "next_decision",
    "next_action",
    "next_segment",
    "next_keyword_idea",
    "insights",
    "reasoning"
  ],
  "additionalProperties": false
}

parameters.jsCode:
const json = $input.item.json;
const validationErrors = [];

const requiredKeys = ['next_decision', 'next_action', 'next_segment', 'next_keyword_idea', 'insights', 'reasoning'];
for (const key of requiredKeys) {
  if (!(key in json)) {
    validationErrors.push(`Missing required key: ${key}`);
  }
}

if (!['improve', 'pause', 'scale'].includes(json.next_decision)) {
  validationErrors.push('Invalid next_decision');
}

if (!['Cold', 'Middle', 'Hot', 'Current'].includes(json.next_segment)) {
  validationErrors.push('Invalid next_segment');
}

if (json.next_action?.length > 200) {
  validationErrors.push('next_action exceeds max length');
}

if (json.next_keyword_idea?.length > 100) {
  validationErrors.push('next_keyword_idea exceeds max length');
}

if (!Array.isArray(json.insights) || json.insights.length < 2 || json.insights.length > 4) {
  validationErrors.push('insights must have 2-4 items');
}

if (json.reasoning?.length > 500) {
  validationErrors.push('reasoning exceeds max length');
}

if (validationErrors.length > 0) {
  throw new Error(`Schema validation failed:\n${validationErrors.join('\n')}`);
}

return {
  json: {
    ...json,
    validation_passed: true,
    validated_at: new Date().toISOString()
  }
};
